mapper.select:
WITH selected AS (
    SELECT DISTINCT w.id, w.publication_year, w.title, w.doi
    FROM ${schema}.works_locations loc JOIN ${schema}.works w ON w.id = loc.work_id
    WHERE loc.source_id = #{sourceId} AND loc.work_id > #{after}
    AND w.publication_year >= #{yearFrom}
    AND w.publication_year <= #{yearTo}
    ORDER BY w.id LIMIT 500
)
SELECT s.id AS work_id, s.publication_year AS year, s.title, s.doi,
       COALESCE((
         SELECT string_agg(a.display_name, ';' ORDER BY a.id)
         FROM ${schema}.works_authorships wa JOIN ${schema}.authors a ON a.id = wa.author_id
         WHERE wa.work_id = s.id
       ), '') AS authors
FROM selected s ORDER BY s.id

SELECT work_id, year, title, doi, authors FROM v2_openalex_work WHERE source_id = #{sourceId} AND doi = #{doi}
UNION ALL
 AND w.doi = #{doi} ORDER BY work_id

SELECT work_id, year, title, doi, authors FROM v2_openalex_work WHERE source_id = #{sourceId} AND year = #{year}
UNION ALL
 AND w.publication_year = #{year} ORDER BY work_id
